ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'content/question-bank/ssc/physics/chapter-2'
DOC=ROOT/'docs/question-bank/ssc-physics'
TOPIC='২য় অধ্যায়: গতি'
PAGE='নিজস্ব অনুশীলনী; বোর্ড-প্রশ্ন নয়; মূল বইয়ের পৃষ্ঠা যাচাই বাকি'
items=[]
audit=[]

def fmt(x):
    x=F(x)
    d=(Decimal(x.numerator)/Decimal(x.denominator)).quantize(Decimal('.000001'),rounding=ROUND_HALF_UP)
    return format(d,'f').rstrip('0').rstrip('.') or '0'

def add(kind,text,explanation,family,calc=None,**kw):
    items.append(dict(type=kind,text=text,explanation=explanation,page=PAGE,difficulty=kw.pop('difficulty','MEDIUM'),**kw))
    meta=dict(index=len(items),kind=kind,family=family,teacherApproved=False,originalPractice=True)
    if calc:meta['calculation']=calc
    audit.append(meta)

def mcq(q,good,wrong,why,family,calc=None):
    opts=[str(good),*map(str,wrong)]
    assert len(opts)==len(set(opts))==4,(q,opts)
    pos=sum(x['type']=='MCQ' for x in items)%4
    opts.insert(pos,opts.pop(0))
    add('MCQ',q,why,family,calc,options=dict(zip('ABCD',opts)),correct='ABCD'[pos])

