# Every family supplies exact input/output evidence; rational arithmetic avoids drift.
def calculation(f,n):
    u=4+n; a=F(n+2,2); t=4+n
    if f=='speed':
        d=120+n*30;t=10+n
        r=F(d,t);p=dict(d=d,t=t)
        return f'একটি সাইকেল {t} s সময়ে মোট {d} m পথ যায়। গড় দ্রুতি কত?',r,' m/s',f'গড় দ্রুতি = মোট দূরত্ব/সময় = {d}/{t} ≈ {fmt(r)} m/s।',p
    if f=='kmh-ms':
        v=18+n*9;r=F(v)*5/18
        return f'এক গাড়ির দ্রুতি {v} km/h। m/s এককে কত?',r,' m/s',f'km/h থেকে m/s-এ 5/18 দিয়ে গুণ; {v}×5/18 = {fmt(r)} m/s।',dict(v=v)
    if f=='ms-kmh':
        v=5+n*2;r=F(v)*18/5
        return f'এক ট্রলির দ্রুতি {v} m/s। km/h এককে প্রকাশ করো।',r,' km/h',f'm/s থেকে km/h-এ 18/5 দিয়ে গুণ; {v}×18/5 = {fmt(r)} km/h।',dict(v=v)
    if f=='uniform-distance':
        v=3+n;t=12+n;r=v*t
        return f'এক বস্তু সোজা পথে একই দিকে {v} m/s ধ্রুব বেগে {t} s চলে। সরণের মান কত?',r,' m',f's = vt = {v}×{t} = {r} m।',dict(v=v,t=t)
    if f=='acceleration':
        v=u+3*t;r=F(v-u,t)
        return f'এক সরলপথে বেগ {t} s-এ +{u} m/s থেকে +{v} m/s হয়। গড় ত্বরণ কত?',r,' m/s²',f'a = (v−u)/t = ({v}−{u})/{t} = {fmt(r)} m/s²।',dict(u=u,v=v,t=t)
    if f=='final-speed':
        r=u+a*t
        return f'সোজা পথে আদিবেগ +{u} m/s, ধ্রুব ত্বরণ +{fmt(a)} m/s²। {t} s পরে বেগ কত?',r,' m/s',f'v = u+at = {u}+{fmt(a)}×{t} = {fmt(r)} m/s।',dict(u=u,a=str(a),t=t)
    if f=='rest-distance':
        r=a*t*t/2
        return f'স্থির অবস্থা থেকে সোজা পথে {fmt(a)} m/s² ধ্রুব ত্বরণে {t} s চললে সরণ কত?',r,' m',f'u = 0; s = ½at² = ½×{fmt(a)}×{t}² = {fmt(r)} m।',dict(a=str(a),t=t)
    if f=='moving-distance':
        r=u*t+a*t*t/2
        return f'একই সরল পথে u = +{u} m/s, a = +{fmt(a)} m/s² হলে {t} s-এ সরণ কত?',r,' m',f's = ut+½at² = {u}×{t}+½×{fmt(a)}×{t}² = {fmt(r)} m।',dict(u=u,a=str(a),t=t)
    if f=='average-velocity':
        v=u+12+n;r=F(u+v,2)
        return f'এক বস্তু সরলপথে ধ্রুব ত্বরণে আদিবেগ +{u} m/s থেকে শেষবেগ +{v} m/s পায়। ঐ সময়ে গড় বেগ কত?',r,' m/s',f'ধ্রুব ত্বরণে গড় বেগ = (u+v)/2 = ({u}+{v})/2 = {fmt(r)} m/s।',dict(u=u,v=v)
    if f=='stop-time':
        u=12+n*2;b=2+n%3;r=F(u,b)
        return f'+{u} m/s বেগে চলা বস্তুতে বেগের বিপরীতে {b} m/s² ধ্রুব মন্দন প্রয়োগ করা হলো। থামতে সময় কত?',r,' s',f'0 = u−bt; থামার সময় = u/b = {u}/{b} ≈ {fmt(r)} s।',dict(u=u,b=b)
    if f=='stop-distance':
        u=10+n*2;b=2+n%4;r=F(u*u,2*b)
        return f'{u} m/s দ্রুতি থেকে {b} m/s² ধ্রুব মন্দনে সোজা পথে থামলে থামার দূরত্ব কত?',r,' m',f'v² = u²−2bs; v = 0 দিলে s = u²/(2b) = {u}²/(2×{b}) ≈ {fmt(r)} m।',dict(u=u,b=b)
    if f=='velocity-distance':
        a=n+1;t=2+n;u=3+n;v=u+a*t;s=F(u+v,2)*t;r=F(v)
        return f'একই দিকে u = {u} m/s ও ধ্রুব a = {a} m/s² নিয়ে s = {fmt(s)} m চললে শেষবেগের মান কত?',r,' m/s',f'v² = u²+2as = {u}²+2×{a}×{fmt(s)} = {v*v}; একই দিকে চলায় v = {v} m/s।',dict(u=u,a=a,s=str(s))
    if f=='drop-distance':
        t=2+n;r=F(10*t*t,2)
        return f'একটি বস্তু স্থির অবস্থা থেকে ছাড়া হলো। বায়ুর বাধা ছাড়া {t} s-এ কত নিচে নামবে? g = 10 m/s² ধরো; ততক্ষণে মাটি পায়নি।',r,' m',f'h = ½gt² = ½×10×{t}² = {fmt(r)} m।',dict(g=10,t=t)
    if f=='drop-speed':
        t=2+n;g=F(98,10);r=g*t
        return f'স্থির অবস্থা থেকে মুক্তপতনে {t} s পর দ্রুতির মান কত? g = 9.8 m/s², বায়ুর বাধা নেই এবং ততক্ষণে মাটিতে পৌঁছায়নি।',r,' m/s',f'v = gt = 9.8×{t} = {fmt(r)} m/s, নিচের দিকে।',dict(g=str(g),t=t)
    if f=='up-time':
        u=20+n*5;r=F(u,10)
        return f'এক বস্তু সোজা ওপরে {u} m/s বেগে নিক্ষিপ্ত। g = 10 m/s² এবং বায়ুর বাধা নেই। সর্বোচ্চ বিন্দুতে পৌঁছাতে সময় কত?',r,' s',f'ওপরে ধনাত্মক; v = u−gt = 0, তাই t = {u}/10 = {fmt(r)} s।',dict(u=u,g=10)
    if f=='up-height':
        u=10+n*4;r=F(u*u,20)
        return f'ভূমি থেকে সোজা ওপরে {u} m/s বেগে ছোড়া বস্তুর সর্বোচ্চ উচ্চতা কত? g = 10 m/s², বায়ুর বাধা নেই।',r,' m',f'সর্বোচ্চ বিন্দুতে v = 0; h = u²/(2g) = {u}²/20 = {fmt(r)} m।',dict(u=u,g=10)
    if f=='relative-same':
        fast=12+n;slow=4+n%3;r=fast-slow
        return f'একই দিকে সমান্তরাল সরলপথে A ও B-এর বেগ যথাক্রমে {fast} ও {slow} m/s। B-এর তুলনায় A-এর আপেক্ষিক দ্রুতির মান কত?',r,' m/s',f'একই দিকে আপেক্ষিক বেগ = {fast}−{slow} = {r} m/s।',dict(fast=fast,slow=slow)
    if f=='meeting-time':
        v=4+n;w=6+n;gap=(v+w)*(10+n);r=F(gap,v+w)
        return f'সরলপথে {gap} m দূরে থাকা দুই ব্যক্তি পরস্পরের দিকে {v} ও {w} m/s ধ্রুব দ্রুতিতে একই সময়ে চলা শুরু করে। দেখা হতে সময় কত?',r,' s',f'নিকটায়নের হার = {v}+{w} = {v+w} m/s; t = {gap}/{v+w} = {fmt(r)} s।',dict(v=v,w=w,gap=gap)
    if f=='vt-area':
        v=8+n;t=6+n;r=F(v*t,2)
        return f'একটি v-t রেখা (0 s, 0 m/s) থেকে ({t} s, +{v} m/s) পর্যন্ত সরলরেখা। এই সময়ে সরণ কত?',r,' m',f'বেগ-সময় ক্ষেত্রফল ত্রিভুজ; s = ½×{t}×{v} = {fmt(r)} m।',dict(v=v,t=t)
    if f=='xt-slope':
        x=10+n;y=x+(n+3)*4;r=F(y-x,4)
        return f'অবস্থান-সময় সারণিতে t = 2 s-এ x = {x} m এবং t = 6 s-এ x = {y} m। মাঝের x-t রেখা সরল হলে বেগ কত?',r,' m/s',f'ঢাল = Δx/Δt = ({y}−{x})/(6−2) = {fmt(r)} m/s।',dict(x=x,y=y,t1=2,t2=6)
    if f=='equal-distance-average':
        v=6+n;w=10+n;r=F(2*v*w,v+w)
        return f'এক যাত্রার প্রথম অর্ধেক দূরত্ব {v} m/s ও বাকি অর্ধেক {w} m/s ধ্রুব দ্রুতিতে অতিক্রান্ত হয়। বিরতি নেই। পুরো পথের গড় দ্রুতি কত?',r,' m/s',f'সমান দূরত্বে গড় = 2v₁v₂/(v₁+v₂) = 2×{v}×{w}/({v}+{w}) ≈ {fmt(r)} m/s।',dict(v=v,w=w)
    if f=='equal-time-average':
        v=6+n;w=14+n;r=F(v+w,2)
        return f'প্রথম 10 s-এ দ্রুতি {v} m/s ও পরের 10 s-এ {w} m/s ধ্রুব। গড় দ্রুতি কত?',r,' m/s',f'সমান সময়ের জন্য গড় = (v₁+v₂)/2 = ({v}+{w})/2 = {fmt(r)} m/s।',dict(v=v,w=w)
    if f=='nth-second':
        sec=2+n;u=2+n;a=2;r=F(u)+F(a,2)*(2*sec-1)
        return f'একই দিকে u = {u} m/s ও ধ্রুব a = 2 m/s²। যাত্রার {sec}-তম এক সেকেন্ডে কত দূরত্ব যায়?',r,' m',f'n-তম সেকেন্ডের পথ = s(n)−s(n−1) = u×1+½a(2n−1)×1² = {u}+({2*sec-1}) = {fmt(r)} m। এখানে বেগের দিক বদলায় না।',dict(u=u,a=a,n=sec)
    if f=='frequency':
        N=20+n*5;t=10+n;r=F(N,t)
        return f'একটি আদর্শ পর্যাবৃত্ত গতিতে {t} s-এ {N}টি পূর্ণ চক্র হয়। কম্পাঙ্ক কত?',r,' Hz',f'f = N/t = {N}/{t} ≈ {fmt(r)} Hz।',dict(N=N,t=t)
    raise ValueError(f)

FAMILIES=['speed','kmh-ms','ms-kmh','uniform-distance','acceleration','final-speed','rest-distance','moving-distance','average-velocity','stop-time','stop-distance','velocity-distance','drop-distance','drop-speed','up-time','up-height','relative-same','meeting-time','vt-area','xt-slope','equal-distance-average','equal-time-average','nth-second','frequency']
for f in FAMILIES:
    for n in range(10):
        q,r,unit,why,p=calculation(f,n);r=F(r)
        candidates=[r*2,r/2,r*F(3,2),r+1,r-1,r*10,r/10]
        wrong=[]
        for x in candidates:
            s=fmt(x)+unit
            if x>=0 and s!=fmt(r)+unit and s not in wrong:wrong.append(s)
            if len(wrong)==3:break
        mcq(q,fmt(r)+unit,wrong,why,f,dict(params={k:str(v) for k,v in p.items()},expected=str(r),unit=unit))
assert Counter(q['type'] for q in items)['MCQ']==300

SHORTS='''একই যাত্রী বাসের সাপেক্ষে স্থির কিন্তু রাস্তার সাপেক্ষে গতিশীল—ব্যাখ্যা করো।|বাসে আসন না বদলালে যাত্রীর বাসের তুলনায় অবস্থান বদলায় না। বাস চললে রাস্তার তুলনায় তার অবস্থান সময়ের সঙ্গে বদলায়; তাই স্থিতি ও গতি প্রসঙ্গনির্ভর।
গতির বর্ণনায় প্রসঙ্গ কাঠামো নির্দিষ্ট করা দরকার কেন?|কোনো অবস্থান ও তার পরিবর্তন অন্য কিছুর তুলনায় মাপা হয়। প্রসঙ্গ না বললে একই বস্তুকে স্থির বা চলমান বলার অর্থ অস্পষ্ট থাকে।
দূরত্ব ও সরণের দুটি পার্থক্য লেখো।|দূরত্ব প্রকৃত পথের মোট দৈর্ঘ্য এবং স্কেলার। সরণ শুরু থেকে শেষ অবস্থানের দিকযুক্ত পরিবর্তন; একই শুরু-শেষে পথ বদলালে দূরত্ব বদলালেও সরণ বদলায় না।
সরণের মান দূরত্বের চেয়ে বেশি হয় না কেন?|দুটি অবস্থানের মধ্যে সরলরেখার ব্যবধান সর্বনিম্ন। সরণের মান সেই ব্যবধান; বাস্তব পথ তার সমান বা বড়।
কখন সরণের মান ও দূরত্ব সমান হয়?|একই সরলরেখায় একদিকে চললে, দিক না বদলালে। বাঁক বা ফিরে আসা থাকলে সাধারণত দূরত্ব বড় হয়।
কোনো পথ ঘুরে শুরুর বিন্দুতে ফিরলে গড় বেগ শূন্য হলেও গড় দ্রুতি শূন্য নয় কেন?|মোট সরণ শূন্য বলে মোট সময় দিয়ে ভাগে গড় বেগ শূন্য। কিন্তু মোট অতিক্রান্ত পথ অশূন্য হওয়ায় সসীম সময়ে গড় দ্রুতি ধনাত্মক।
দ্রুতি ও বেগের পার্থক্য উদাহরণসহ লেখো।|দ্রুতি শুধু গতির মান, যেমন 5 m/s। বেগে দিকও লাগে, যেমন পূর্বে 5 m/s; দিক বদলালে দ্রুতি একই থাকলেও বেগ বদলায়।
স্পিডোমিটারকে সম্পূর্ণ বেগ-নির্দেশক বলা যায় না কেন?|এটি সাধারণত গতির মান বা তাৎক্ষণিক দ্রুতি দেখায়। বেগ নির্দিষ্ট করতে দিকও প্রয়োজন, যা শুধু স্পিডোমিটার দেয় না।
গড় দ্রুতি সবসময় প্রথম ও শেষ দ্রুতির গড় নয় কেন?|মোট দূরত্ব ও মোট সময় পুরো গতির ওপর নির্ভর করে। শুধু দুই প্রান্তের মান দিয়ে মাঝের গতি জানা যায় না; বিশেষ শর্ত ছাড়া গাণিতিক গড় প্রযোজ্য নয়।
সমান সময় ভিন্ন দ্রুতিতে চললে গাণিতিক গড় প্রযোজ্য হয় কেন?|প্রতি সময় t হলে পথ v₁t ও v₂t। মোট পথকে 2t দিয়ে ভাগ করলে (v₁+v₂)/2 হয়।
সমান দূরত্বে দুটি ভিন্ন দ্রুতির জন্য গড় দ্রুতির সূত্র দেখাও।|প্রতি দূরত্ব d হলে সময় d/v₁ ও d/v₂। গড় = 2d/(d/v₁+d/v₂) = 2v₁v₂/(v₁+v₂)।
সমবেগ ও সমদ্রুতির পার্থক্য লেখো।|সমবেগে বেগের মান ও দিক দুটোই স্থির। সমদ্রুতিতে শুধু মান স্থির; বৃত্তাকার পথে দিক বদলাতে পারে।
ত্বরণ শূন্য হলেই বস্তু স্থির—এ বক্তব্য খণ্ডন করো।|সমবেগে চলা বস্তুর বেগের পরিবর্তন শূন্য, তাই ত্বরণ শূন্য। কিন্তু বেগ অশূন্য হলে সে চলমানই থাকে।
সমদ্রুতিতে বৃত্তাকার গতিতে ত্বরণ থাকে কেন?|বেগ একটি ভেক্টর। বৃত্তে চলতে বেগের দিক পরিবর্তিত হয়; তাই একই দ্রুতি হলেও বেগ-পরিবর্তন এবং ত্বরণ থাকে।
ঋণাত্মক ত্বরণ ও মন্দনকে সবক্ষেত্রে সমার্থক বলা ভুল কেন?|ঋণাত্মক ত্বরণ বাছাই করা ঋণাত্মক অক্ষের দিক নির্দেশ করে। বেগও ঐ দিকে হলে দ্রুতি বাড়ে; মন্দন বলতে দ্রুতির হ্রাস বোঝায়।
কোন শর্তে ত্বরণে বস্তুর দ্রুতি কমে?|বেগ ও ত্বরণ বিপরীত দিকে হলে। একই দিকে হলে দ্রুতির মান বাড়ে; তাই অক্ষের চিহ্নের বদলে আপেক্ষিক দিক গুরুত্বপূর্ণ।
সমত্বরণ কাকে বলে? একটি আদর্শ উদাহরণ দাও।|সমান সময়ে সমান বেগ-পরিবর্তন হলে ত্বরণ ধ্রুব। পৃথিবীর কাছাকাছি বায়ুর বাধা ছাড়া মুক্তপতন আনুমানিক সমত্বরণে গতি।
v = u + at সমীকরণের শর্ত ও প্রতীকগুলোর অর্থ লেখো।|ত্বরণ a ধ্রুব ধরে u আদিবেগ, t অতিবাহিত সময় ও v শেষবেগ। একটি নির্দিষ্ট অক্ষে সব ভেক্টর রাশির চিহ্ন ধারাবাহিক রাখতে হয়।
s = ut + ½at² থেকে পাওয়া মান কখন মোট দূরত্ব নয়?|সমীকরণে s সরণ। সময়ের মধ্যে দিক বদলালে বিপরীত দিকের সরণ বিয়োগ হয়; মোট পথ পেতে প্রতিটি অংশের দৈর্ঘ্য যোগ করতে হয়।
ধ্রুব ত্বরণে সময় বাদ দিয়ে কোন সমীকরণ ব্যবহার করবে এবং কী সাবধানতা নেবে?|v² = u² + 2as। একই অক্ষ অনুযায়ী u, a, s-এর চিহ্ন নিতে হয়; v² থেকে বেগের মান পেলেও দিক শারীরিক পরিস্থিতি দিয়ে নির্ধারণ করতে হয়।
বেগ-সময় লেখচিত্রের ঢাল থেকে ত্বরণ কেন পাওয়া যায়?|ঢাল হলো উল্লম্ব বেগ-পরিবর্তনকে অনুভূমিক সময়-পরিবর্তন দিয়ে ভাগ। এটিই Δv/Δt বা গড় ত্বরণ; সরলরেখায় ধ্রুব ত্বরণ।
অবস্থান-সময় লেখচিত্রের ঢাল কী দেয়? অনুভূমিক অংশের অর্থ কী?|ঢাল Δx/Δt বেগ দেয়। অনুভূমিক অংশে অবস্থান অপরিবর্তিত বলে বস্তু ঐ সময়ে স্থির।
বেগ-সময় লেখচিত্রের ক্ষেত্রফলে নিচের অংশ ঋণাত্মক কেন?|সময় অক্ষের নিচে বেগ ঋণাত্মক দিকের। ক্ষেত্রফল বীজগাণিতিকভাবে নিলে সেই দিকের সরণ বিয়োগ হয়; মোট দূরত্বে পরম ক্ষেত্রফল যোগ করতে হয়।
বেগ-সময় রেখা অক্ষের ওপরে হলেও ঋণাত্মক ঢাল থাকতে পারে কি?|হ্যাঁ, ধনাত্মক বেগ কমতে থাকলে রেখা ওপরে থেকেও নিচের দিকে ঢালে। তখন বেগ ধনাত্মক ও ত্বরণ ঋণাত্মক।
দূরত্ব-সময় ও অবস্থান-সময় লেখচিত্র এক নয় কেন?|দূরত্ব মোট সঞ্চিত পথ, যা কমে না। অবস্থান বাছাই করা মূলবিন্দুর তুলনায় দিকযুক্ত; ফিরে এলে এটি কমতেও পারে।
ধ্রুব ত্বরণে গড় বেগ (u+v)/2 হওয়ার যুক্তি দাও।|বেগ-সময় রেখা সরল; বীজগাণিতিক ক্ষেত্রফল (u+v)t/2। সেটিকে t দিয়ে ভাগ করলে গড় বেগ (u+v)/2 হয়।
স্থির থেকে সমত্বরণে 1, 2, 3 সময়ে সরণ 1:4:9 হলেও পরপর সময়পর্বের পথ 1:3:5 কেন?|মোট সরণ t²-এর সমানুপাতিক। পরপর অংশ পেতে মোটগুলো বিয়োগ করতে হয়: 1, 4−1 = 3, 9−4 = 5।
একই মন্দনে আদিবেগ দ্বিগুণ হলে থামার দূরত্ব কত গুণ হয়? যুক্তি দাও।|থামার দূরত্ব s = u²/(2b)। b একই রেখে u দ্বিগুণ করলে s চারগুণ হয়; থামার সময় হয় দ্বিগুণ।
প্রতিক্রিয়া-দূরত্ব ও ব্রেকিং-দূরত্বের পার্থক্য লেখো।|বিপদ দেখে ব্রেক কাজ শুরু হওয়ার আগের প্রতিক্রিয়া সময়ে গাড়ির চলা পথ প্রতিক্রিয়া-দূরত্ব। ব্রেকের মন্দনে থামা পর্যন্ত পথ ব্রেকিং-দূরত্ব; মোট থামার পথ উভয়ের যোগ।
মুক্তপতনে সব ভরের বস্তু একই ত্বরণে পড়ে—কোন শর্তে বলা হয়?|একই স্থানে ও প্রায় একই উচ্চতায়, বায়ুর বাধা ও অন্য প্রভাব উপেক্ষা করলে। বাস্তবে বায়ুর বাধা আকৃতি ও পৃষ্ঠভেদে পতন বদলাতে পারে।
হাত থেকে ছেড়ে দেওয়া ও নিচে ছুড়ে দেওয়া বস্তুর আদিবেগের পার্থক্য কী?|স্থির হাত থেকে ছেড়ে দিলে আদিবেগ শূন্য ধরা হয়। নিচে ছুড়ে দিলে আদিবেগ নিচের দিকে অশূন্য; তাই একই উচ্চতায় পতনকাল ভিন্ন হতে পারে।
উল্লম্ব নিক্ষেপে সর্বোচ্চ উচ্চতায় বেগ শূন্য কিন্তু ত্বরণ শূন্য নয় কেন?|সেখানে বস্তু ওঠা থেকে নামার দিকে যায় বলে মুহূর্তে বেগ শূন্য। মহাকর্ষের প্রভাব তখনও নিচে থাকে, তাই ত্বরণ g।
ওপরের দিক ধনাত্মক ধরলে মুক্তগতির ত্বরণ ওঠা ও নামায় কী হবে?|দুই পর্যায়েই ত্বরণ −g। নামার সময় বেগও ঋণাত্মক হয়; মহাকর্ষের দিক বদলায় না।
বায়ুর বাধা না থাকলে একই উচ্চতায় ফেরার দ্রুতি আদিদ্রুতির সমান কেন?|v² = u²−2gΔy; একই উচ্চতায় Δy = 0। তাই বেগের মান সমান, কিন্তু ফেরার দিকে চিহ্ন বিপরীত।
উল্লম্বভাবে ছোড়া বস্তুতে মোট উড্ডয়নকাল 2u/g কখন প্রযোজ্য?|যখন বস্তু নিক্ষেপের একই উচ্চতায় ফিরে আসে, g ধ্রুব এবং বায়ুর বাধা নেই। ভিন্ন উচ্চতায় নামলে এই সূত্র সরাসরি চলে না।
একই দিকে চলা বস্তুর আপেক্ষিক বেগে বিয়োগ কেন হয়?|একই সময়ে উভয়েই একই দিকের দূরত্ব অতিক্রম করে। তাদের বিচ্ছেদের পরিবর্তন দুটি দিকযুক্ত বেগের পার্থক্য।
পরস্পরের দিকে এগোনো বস্তুর দেখা হওয়ার সময় কীভাবে পাবে?|দ্রুতি ধ্রুব হলে নিকটায়নের হার দুই দ্রুতির যোগফল। প্রাথমিক বিচ্ছেদকে সেই যোগফল দিয়ে ভাগ করতে হয়।
সমবেগের দুই গাড়ির বিচ্ছেদ অপরিবর্তিত থাকা কী নির্দেশ করে?|একই দিক ও একই বেগ হলে আপেক্ষিক বেগ শূন্য হয়। ফলে রাস্তার তুলনায় দুটিই চললেও পরস্পরের তুলনায় অবস্থান অপরিবর্তিত।
দুটি বস্তু একই অবস্থানে থাকা মানেই একই বেগ নয় কেন?|একটি দ্রুত অন্যটিকে অতিক্রম করার মুহূর্তে তাদের অবস্থান মিলে যায়। কিন্তু তাদের অবস্থান পরিবর্তনের হার বা বেগ আলাদা থাকতে পারে।
অবস্থান-সময় দুটি রেখা ছেদ করলে কী বোঝা যায়? ঢাল সমান হওয়া কি দরকার?|একই সময়ে একই অক্ষ বরাবর একই অবস্থান বোঝায়। ঢাল বা বেগ সমান হওয়া জরুরি নয়; অতিক্রমের সময় ঢাল আলাদা হতে পারে।
পর্যাবৃত্ত ও দোলন গতির সম্পর্ক কী?|দোলন গতি সাম্যাবস্থার দুদিকে পুনরাবৃত্ত আগা-পিছা চলা। আদর্শ নিয়মিত দোলন পর্যাবৃত্ত; কিন্তু সব পর্যাবৃত্ত গতি দোলন নয়, যেমন বৃত্তাকার আবর্তন।
ঘূর্ণন ও চলন গতির দুটি উদাহরণ দিয়ে পার্থক্য লেখো।|স্থির অক্ষে পাখা ঘোরা ঘূর্ণন; বিভিন্ন বিন্দু অক্ষের চারদিকে ঘোরে। সোজা পথে ঘূর্ণন ছাড়া বাক্স এগোনো চলন; বিন্দুগুলো একই সরণ পায়।
পর্যায়কাল ও কম্পাঙ্কের সম্পর্ক ব্যাখ্যা করো।|একটি চক্রে T সেকেন্ড লাগলে প্রতি সেকেন্ডে 1/T চক্র হয়। তাই f = 1/T; একক যথাক্রমে s ও Hz।
অর্ধবৃত্ত ঘোরা বস্তুর পথ ও সরণের মান কীভাবে আলাদা করবে?|ব্যাসার্ধ r হলে অর্ধবৃত্তের পথ πr। শুরু-শেষ বৃত্তের বিপরীত প্রান্ত বলে সরণের মান ব্যাস 2r; দিক হবে প্রথম থেকে শেষ প্রান্তের দিকে।
পূর্ণ বৃত্তে এক পাক গেলে গড় বেগ ও গড় দ্রুতির তুলনা করো।|সরণ শূন্য হওয়ায় গড় বেগ শূন্য। মোট পথ পরিধি 2πr হওয়ায় সময় T হলে গড় দ্রুতি 2πr/T।
একই সরলপথে পূর্বকে ধনাত্মক নিলে পশ্চিমমুখী বেগ কীভাবে লিখবে? দ্রুতি কি ঋণাত্মক?|পশ্চিমমুখী বেগ ঋণাত্মক, যেমন −5 m/s। দ্রুতি বেগের মান, তাই 5 m/s; এটি ঋণাত্মক নয়।
যাত্রাপথে বিরতি থাকলে গড় দ্রুতি নির্ণয়ে বিরতির সময় বাদ দেওয়া ঠিক কি?|সম্পূর্ণ যাত্রার গড় দ্রুতির জন্য বাদ দেওয়া ঠিক নয়; মোট অতিবাহিত সময়ের মধ্যে বিরতিও থাকে। শুধু চলমান সময়ের গড় চাইলে তা আলাদা করে উল্লেখ করতে হয়।
বেগের পরিবর্তন ও ত্বরণকে একই রাশি বলা যায় না কেন?|বেগের পরিবর্তনের একক m/s। ত্বরণ হলো সেই পরিবর্তন ঘটার হার, তাই একক m/s²; একই বেগ-পরিবর্তন কম সময়ে ঘটলে ত্বরণ বেশি।
বেগ-সময় রেখায় একটি মুহূর্তে বেগ শূন্য হলেই মোট সরণ শূন্য কি?|না। মোট সরণ পুরো সময়ের বীজগাণিতিক ক্ষেত্রফল। শুধু একটি মুহূর্তে বেগ শূন্য হলে আগে-পরে অর্জিত সরণ নিজে বাতিল হয় না।
সমত্বরণের সূত্রে একক সামঞ্জস্যের একটি উদাহরণ দাও।|u যদি km/h-এ দেওয়া থাকে এবং a m/s² ও t s-এ থাকে, আগে u-কে 5/18 দিয়ে গুণ করে m/s-এ নিতে হয়। তারপর v = u+at ব্যবহার করলে একক মেলে।'''
for line in SHORTS.splitlines():
    q,ans=line.split('|');add('SQ',q,ans,'concept-short')
assert Counter(q['type'] for q in items)['SQ']==50
for f in ['acceleration','final-speed','moving-distance','stop-distance','drop-distance','up-height','meeting-time','vt-area','equal-distance-average','nth-second']:
    for n in range(5):
        q,r,unit,why,p=calculation(f,n)
        add('SQ',q.rstrip('।?')+'। সূত্র ও ধাপসহ হিসাব দেখাও।',why,'short-'+f,dict(params={k:str(v) for k,v in p.items()},expected=str(r),unit=unit,baseFamily=f))

# A CQ has four parts and two explicitly calculated application/analysis answers.
def cq(f,n,stem,definition,reason,gq,gs,hq,hs,params):
    pairs=[definition,reason,(gq,gs),(hq,hs)]
    parts=[dict(label=l,marks=m,question=q,solution=s) for l,m,(q,s) in zip('কখগঘ',[1,2,3,4],pairs)]
    add('CQ',stem,'ধ্রুব ত্বরণের সূত্র কেবল সংশ্লিষ্ট সমত্বরণ পর্বে ব্যবহার করতে হবে। দিক অনুযায়ী চিহ্ন এবং সামঞ্জস্যপূর্ণ একক নাও; প্রয়োজনমতো ছয় দশমিক পর্যন্ত আসন্ন মান।',f,dict(params={k:str(v) for k,v in params.items()},variant=n+1),parts=parts,difficulty='HARD')

DEF_A=('ত্বরণ কী?','সময় প্রতি বেগের পরিবর্তনের হার; a = Δv/Δt।')
DEF_V=('গড় বেগ কী?','মোট সরণকে মোট অতিবাহিত সময় দিয়ে ভাগ করলে গড় বেগ পাওয়া যায়।')
DEF_S=('গড় দ্রুতি কী?','মোট অতিক্রান্ত পথকে মোট অতিবাহিত সময় দিয়ে ভাগ করলে গড় দ্রুতি পাওয়া যায়।')
WHY_SIGN=('বেগ ও ত্বরণের চিহ্ন নির্ধারণে কী নিয়ম মানতে হবে?','একটি অক্ষের ধনাত্মক দিক আগে বেছে নিতে হয়। একই অক্ষ অনুযায়ী সব বেগ, সরণ ও ত্বরণের চিহ্ন ধারাবাহিকভাবে নিতে হবে।')
WHY_AREA=('বেগ-সময় লেখচিত্রের ক্ষেত্রফল কেন সরণ নির্দেশ করে?','প্রতি ক্ষুদ্র সময়ে বেগ × সময় সরণ দেয়। সব ক্ষুদ্র অংশের দিকযুক্ত যোগফলই লেখচিত্রের বীজগাণিতিক ক্ষেত্রফল।')
WHY_G=('পতনের ত্বরণ ভরভেদে আলাদা ধরা হয়নি কেন?','একই স্থানে বায়ুর বাধা ছাড়া g সব বস্তুর জন্য একই ধরা হয়। এই আদর্শ মডেলে ভরের প্রভাব পতনের সমীকরণে নেই।')

for n in range(5):
    u=4+n;a=2+n;t=5+n;v=u+a*t;s=F(u+v,2)*t
    cq('cq-accel',n,f'একটি ট্রলি সোজা পথে +{u} m/s আদিবেগে +{a} m/s² ধ্রুব ত্বরণ নিয়ে {t} s চলে। পুরো সময় দিক অপরিবর্তিত।',DEF_A,WHY_SIGN,
       'শেষবেগ নির্ণয় করো।',f'v = u+at = {u}+{a}×{t} = {v} m/s।',
       'ঐ সময়ের সরণ দুইভাবে বের করে ফলের মিল দেখাও।',f's = ut+½at² = {u}×{t}+½×{a}×{t}² = {fmt(s)} m। আবার (u+v)t/2 = ({u}+{v})×{t}/2 = {fmt(s)} m। দিক একই থাকায় দূরত্বও এই মান।',dict(u=u,a=a,t=t))
    # 2: braking.
    u=16+n*4;b=2+n;T=F(u,b);S=F(u*u,2*b)
    cq('cq-braking',n,f'একটি গাড়ি সোজা পথে +{u} m/s বেগে চলছে। ব্রেক চাপার সঙ্গে সঙ্গে −{b} m/s² ধ্রুব ত্বরণে থামে। থামার পর আর চলেনি; প্রতিক্রিয়াকাল উপেক্ষা করো।',DEF_A,
       ('ঋণাত্মক ত্বরণ এখানে মন্দন কেন?','বেগ ধনাত্মক এবং ত্বরণ বিপরীত দিকে; ফলে দ্রুতির মান কমে।'),
       'থামতে কত সময় লাগে?',f'v = u−bt; 0 = {u}−{b}t, তাই t = {u}/{b} = {fmt(T)} s।',
       'থামার দূরত্ব নির্ণয় করে পরের দ্বিগুণ সময় পর্যন্ত একই সূত্র বাড়ানো কেন অনুচিত বোঝাও।',f's = u²/(2b) = {u}²/(2×{b}) = {fmt(S)} m। থামার পর গাড়ি স্থির বলা হয়েছে; একই ঋণাত্মক ত্বরণ বাড়ালে বিপরীত দিকে বেগ দেবে, যা উদ্দীপকের সঙ্গে মেলে না।',dict(u=u,b=b))
    # 3: acceleration from endpoints.
    u=3+n;v=15+n*3;t=4+n;a=F(v-u,t);s=F(u+v,2)*t
    cq('cq-endpoint-accel',n,f'এক সরলপথে একটি বস্তুর বেগ {t} s-এ +{u} m/s থেকে +{v} m/s হয়। এই সময়ে ত্বরণ ধ্রুব এবং দিক বদলায় না।',DEF_V,WHY_AREA,
       'ত্বরণ নির্ণয় করো।',f'a = (v−u)/t = ({v}−{u})/{t} = {fmt(a)} m/s²।',
       'গড় বেগ ও সরণ নির্ণয় করে শুধু শেষবেগ × সময় নেওয়ার ভুল বোঝাও।',f'গড় বেগ = ({u}+{v})/2 = {fmt(F(u+v,2))} m/s। s = গড় বেগ × {t} = {fmt(s)} m। শেষবেগ পুরো সময়ে ছিল না; v×t = {v*t} m নিলে বেশি হয়।',dict(u=u,v=v,t=t))
    # 4: eliminate time.
    u=2+n;a=2+n;t=3+n;v=u+a*t;s=F(u+v,2)*t
    cq('cq-distance-final',n,f'এক বস্তু একই সরলপথে +{u} m/s আদিবেগ ও +{a} m/s² ধ্রুব ত্বরণে +{fmt(s)} m সরণ অতিক্রম করে। দিক অপরিবর্তিত থাকে।',DEF_A,WHY_SIGN,
       'শেষবেগ নির্ণয় করো।',f'v² = u²+2as = {u}²+2×{a}×{fmt(s)} = {v*v}। একই দিকে চলায় v = +{v} m/s।',
       'সময় নির্ণয় করে সরণের সূত্র দিয়ে ফল যাচাই করো।',f't = (v−u)/a = ({v}−{u})/{a} = {t} s। ut+½at² = {u}×{t}+½×{a}×{t}² = {fmt(s)} m, প্রদত্ত সরণের সমান।',dict(u=u,a=a,s=s))
    # 5: coasting then stop.
    u=12+n*3;tc=3+n;b=3;tb=F(u,b);sb=F(u*u,2*b);total=u*tc+sb
    cq('cq-coast-brake',n,f'এক গাড়ি প্রথমে {u} m/s ধ্রুব বেগে {tc} s চলে। এরপর একই দিকে চলতে চলতে {b} m/s² ধ্রুব মন্দনে থামে। দুই পর্বের মাঝে বিরতি নেই।',DEF_S,WHY_AREA,
       'শুধু ব্রেকিং পর্বের দূরত্ব নির্ণয় করো।',f'ব্রেকিং সময় = {u}/{b} = {fmt(tb)} s। পথ = u²/(2b) = {u}²/(2×{b}) = {fmt(sb)} m।',
       'পুরো যাত্রার গড় দ্রুতি নির্ণয় করো।',f'মোট পথ = {u}×{tc}+{fmt(sb)} = {fmt(total)} m। মোট সময় = {tc}+{fmt(tb)} = {fmt(tc+tb)} s। গড় দ্রুতি = {fmt(total)}/{fmt(tc+tb)} ≈ {fmt(total/(tc+tb))} m/s; দুই পর্বের সময় সাধারণত সমান নয়।',dict(u=u,tc=tc,b=b))
    # 6: accelerate and cruise.
    a=2+n;t1=4+n;t2=6+n;v=a*t1;s1=F(a*t1*t1,2);total=s1+v*t2
    cq('cq-accelerate-cruise',n,f'এক বাস স্থির থেকে {a} m/s² সমত্বরণে {t1} s চলে। এরপর অর্জিত বেগে আরও {t2} s সরলপথে একই দিকে চলে।',DEF_V,
       ('দ্বিতীয় পর্বে প্রথম পর্বের ত্বরণ ব্যবহার করা যাবে না কেন?','দ্বিতীয় পর্বে বেগ ধ্রুব বলা আছে, তাই ত্বরণ শূন্য। প্রতিটি পর্বের নিজস্ব শর্ত অনুযায়ী সূত্র নিতে হবে।'),
       'প্রথম পর্বের শেষবেগ ও সরণ নির্ণয় করো।',f'v = at = {a}×{t1} = {v} m/s। s₁ = ½at² = {fmt(s1)} m।',
       'পুরো যাত্রার সরণ ও গড় বেগ নির্ণয় করো।',f's₂ = {v}×{t2} = {v*t2} m। মোট s = {fmt(total)} m। মোট t = {t1+t2} s; গড় বেগ = {fmt(total)}/{t1+t2} ≈ {fmt(total/F(t1+t2))} m/s। পুরো যাত্রায় একটিমাত্র ধ্রুব ত্বরণ নেই।',dict(a=a,t1=t1,t2=t2))
    # 7: triangular v-t data.
    peak=12+n*4;up=4+n;down=6+n;area=F(peak*(up+down),2)
    cq('cq-triangle-vt',n,f'বেগ-সময় তথ্য: t = 0-এ v = 0; পরের {up} s-এ বেগ সরলরৈখিকভাবে +{peak} m/s হয়; পরের {down} s-এ সরলরৈখিকভাবে শূন্য হয়।',DEF_A,WHY_AREA,
       'প্রথম ও দ্বিতীয় পর্বের ত্বরণ নির্ণয় করো।',f'a₁ = {peak}/{up} ≈ {fmt(F(peak,up))} m/s²; a₂ = (0−{peak})/{down} ≈ {fmt(-F(peak,down))} m/s²।',
       'মোট সরণ ও গড় দ্রুতি নির্ণয় করো।',f'দুটি ত্রিভুজের ক্ষেত্রফল যোগে s = ½×{peak}×({up}+{down}) = {fmt(area)} m। বেগ ঋণাত্মক নয় বলে পথও একই। গড় দ্রুতি = {fmt(area)}/{up+down} = {fmt(F(peak,2))} m/s।',dict(peak=peak,up=up,down=down))
    # 8: trapezoid v-t profile.
    peak=10+n*2;up=2+n;coast=4+n;down=3+n;area=F(peak*(up+down),2)+peak*coast;tt=up+coast+down
    cq('cq-trapezoid-vt',n,f'এক গাড়ি স্থির থেকে {up} s-এ সমত্বরণে +{peak} m/s হয়; ঐ বেগে {coast} s চলে; শেষে {down} s-এ সমমন্দনে থামে। সম্পূর্ণ পথ সোজা ও একই দিকে।',DEF_S,WHY_AREA,
       'মোট অতিক্রান্ত দূরত্ব নির্ণয় করো।',f'v-t ক্ষেত্রফল = ½×{up}×{peak}+{coast}×{peak}+½×{down}×{peak} = {fmt(area)} m।',
       'গড় দ্রুতি নির্ণয় করে সর্বোচ্চ দ্রুতিকে গড় বলা ভুল কেন বোঝাও।',f'মোট সময় = {up}+{coast}+{down} = {tt} s। গড় = {fmt(area)}/{tt} ≈ {fmt(area/tt)} m/s। ত্বরণ ও মন্দনের সময় দ্রুতি {peak} m/s-এর নিচে থাকে, তাই সর্বোচ্চ মান পুরো সময়ের গড় নয়।',dict(peak=peak,up=up,coast=coast,down=down))
    # 9: position-time extrapolation.
    x0=7+n;t1=2;t2=8;v=3+n;x1=x0+v*t1;x2=x0+v*t2;t3=12;x3=x0+v*t3
    cq('cq-position-time',n,f'সমবেগে চলা এক বস্তুর অবস্থান-সময় তথ্য: t = {t1} s-এ x = {x1} m, t = {t2} s-এ x = {x2} m। একই গতি t = {t3} s পর্যন্ত বজায় থাকে।',DEF_V,
       ('অবস্থান ও সরণ এক জিনিস নয় কেন?','অবস্থান মূলবিন্দুর তুলনায় নির্ধারিত হয়। সরণ দুটি অবস্থানের পার্থক্য; প্রাথমিক অবস্থান শূন্য না হলে শেষ অবস্থানই সরণ নয়।'),
       'বেগ ও t = 0-এর অবস্থান নির্ণয় করো।',f'v = ({x2}−{x1})/({t2}−{t1}) = {v} m/s। x₀ = x₁−vt₁ = {x1}−{v}×{t1} = {x0} m।',
       't = 12 s-এ অবস্থান ও প্রথম 12 s-এর সরণ তুলনা করো।',f'x(12) = {x0}+{v}×12 = {x3} m। সরণ = x(12)−x₀ = {v*12} m। প্রাথমিক অবস্থান {x0} m বলে দুটি সংখ্যামান আলাদা।',dict(x1=x1,x2=x2,t1=t1,t2=t2,t3=t3))
    # 10: return trip.
    d=120+n*30;out=20+n*5;back=30+n*5;avg=F(2*d,out+back)
    cq('cq-return-trip',n,f'একজন শিক্ষার্থী সোজা পথে বাড়ি থেকে {d} m দূরের দোকানে {out} s-এ যায়। একই পথ ধরে {back} s-এ বাড়ি ফেরে। বিরতি নেই; বাড়ি থেকে দোকানের দিক ধনাত্মক।',DEF_V,
       ('ফেরার সময় দূরত্ব কমে না কিন্তু অবস্থান কমে কেন?','দূরত্ব মোট জমা পথ; ফিরে আসাও এতে যোগ হয়। অবস্থান বাড়ির তুলনায় দিকযুক্ত স্থানাঙ্ক; বাড়ির দিকে এলে তা কমে।'),
       'পুরো যাত্রার গড় দ্রুতি নির্ণয় করো।',f'মোট পথ = 2×{d} = {2*d} m। মোট সময় = {out+back} s। গড় দ্রুতি = {2*d}/{out+back} ≈ {fmt(avg)} m/s।',
       'গড় বেগ নির্ণয় করে গড় দ্রুতির সঙ্গে পার্থক্য ব্যাখ্যা করো।',f'প্রথম ও শেষ অবস্থান বাড়ি, তাই সরণ = 0 m। গড় বেগ = 0/{out+back} = 0 m/s। কিন্তু মোট পথ {2*d} m হওয়ায় গড় দ্রুতি {fmt(avg)} m/s; স্কেলার পথ ও ভেক্টর সরণ আলাদা।',dict(d=d,out=out,back=back))
    # 11: reversal under constant acceleration.
    u=8+n*2;b=2;T=F(2*u,b);stop=F(u*u,2*b)
    cq('cq-direction-reversal',n,f'এক বস্তুতে আদিবেগ +{u} m/s এবং পুরো {fmt(T)} s জুড়ে ধ্রুব ত্বরণ −{b} m/s² বজায় থাকে। বস্তু থেমে আবার বিপরীত দিকে চলতে পারে; কোনো বাধা নেই।',DEF_S,WHY_SIGN,
       'কখন দিক বদলায় এবং তার আগে কত দূর যায়?',f'v = {u}−{b}t = 0 হলে t = {fmt(F(u,b))} s। ঐ পর্যন্ত পথ = u²/(2b) = {fmt(stop)} m।',
       'পুরো সময়ের সরণ ও মোট দূরত্ব নির্ণয় করে তুলনা করো।',f's = ut−½bt² = 0 m। বাকি অর্ধসময় বিপরীত দিকে একই {fmt(stop)} m ফিরে আসে। মোট দূরত্ব = {fmt(2*stop)} m। সরণ শূন্য মানে মোট পথ শূন্য নয়; ঋণাত্মক বেগপর্ব আলাদা করতে হয়।',dict(u=u,b=b,T=T))
    # 12: perpendicular path.
    k=10+n*5;east=3*k;north=4*k;t=10+n*2;dist=east+north;disp=5*k
    cq('cq-right-angle-path',n,f'এক পথিক প্রথমে পূর্বে {east} m, এরপর উত্তরে {north} m চলে। পুরো সময় {t} s। পথ দুটি পরস্পর লম্ব।',DEF_V,
       ('দূরত্বের সঙ্গে শুধু দিক যোগ করলেই সরণ হয় না কেন?','পথের মোট দৈর্ঘ্য বাঁকসহ যোগ হয়। সরণ শুরু থেকে শেষের সরলরেখার দিকযুক্ত ব্যবধান; বাঁক থাকলে মান আলাদা।'),
       'মোট দূরত্ব ও গড় দ্রুতি নির্ণয় করো।',f'দূরত্ব = {east}+{north} = {dist} m। গড় দ্রুতি = {dist}/{t} = {fmt(F(dist,t))} m/s।',
       'সরণের মান ও গড় বেগের মান নির্ণয় করে দিক নির্দিষ্ট করো।',f'সরণ = √({east}²+{north}²) = {disp} m। গড় বেগের মান = {disp}/{t} = {fmt(F(disp,t))} m/s। দিক শুরু থেকে শেষ বিন্দুর উত্তর-পূর্বমুখী কর্ণ বরাবর; উত্তর/পূর্ব উপাংশের অনুপাত {north}/{east} = 4/3।',dict(east=east,north=north,t=t))
    # 13: semicircle.
    r=7+n*7;t=11+n;pi=F(22,7);path=pi*r;disp=2*r
    cq('cq-semicircle',n,f'একজন দৌড়বিদ {r} m ব্যাসার্ধের বৃত্তাকার ট্র্যাকের অর্ধেক অংশ {t} s-এ অতিক্রম করে বিপরীত প্রান্তে যায়। π = 22/7 ধরো।',DEF_S,
       ('অর্ধবৃত্তের পথ সরণ নয় কেন?','বক্রপথের দৈর্ঘ্য πr। সরণ শুরু-শেষের সরলরেখা, যা এ ক্ষেত্রে ব্যাস 2r।'),
       'দূরত্ব ও গড় দ্রুতি নির্ণয় করো।',f'পথ = πr = (22/7)×{r} = {fmt(path)} m। গড় দ্রুতি = {fmt(path)}/{t} ≈ {fmt(path/t)} m/s।',
       'গড় বেগের মান নির্ণয় করে গড় দ্রুতির চেয়ে কম কেন দেখাও।',f'সরণ = 2r = {disp} m। গড় বেগের মান = {disp}/{t} ≈ {fmt(F(disp,t))} m/s। যেহেতু 2r < πr, একই সময়ে গড় বেগের মান কম। দিক প্রথম থেকে শেষ প্রান্তের দিকে।',dict(r=r,t=t))
    # 14: full lap.
    r=14+n*7;T=22+n*11;pi=F(22,7);path=2*pi*r
    cq('cq-full-circle',n,f'এক খেলোয়াড় {r} m ব্যাসার্ধের বৃত্তাকার ট্র্যাকে {T} s-এ এক পূর্ণ পাক দেয় এবং শুরুতে ফিরে আসে। পথে থামে না। π = 22/7 ধরো।',DEF_V,
       ('বৃত্তে সমদ্রুতি থাকলেও সমবেগ বলা যায় না কেন?','বেগের দিক ক্রমাগত বদলায়। সমবেগের জন্য মান ও দিক দুটিই অপরিবর্তিত দরকার।'),
       'এক পাকের গড় দ্রুতি নির্ণয় করো।',f'পথ = 2πr = {fmt(path)} m। গড় দ্রুতি = {fmt(path)}/{T} = {fmt(path/T)} m/s।',
       'এক পাকের গড় বেগ ও গতির পর্যায়কাল নির্ণয় করো।',f'সরণ = 0 m, তাই গড় বেগ = 0 m/s। একই গতি পুনরাবৃত্ত হলে এক পাকের পর্যায়কাল = {T} s। গড় বেগ শূন্য হলেও খেলোয়াড়ের চলা বা মোট পথ শূন্য নয়।',dict(r=r,T=T))
    # 15: opposing speeds.
    v=4+n;w=6+n;T=20+n*5;gap=(v+w)*T
    cq('cq-meeting',n,f'একই সরলপথে A ও B-এর প্রাথমিক বিচ্ছেদ {gap} m। তারা একই সময়ে পরস্পরের দিকে {v} m/s ও {w} m/s ধ্রুব দ্রুতিতে হাঁটে।',DEF_V,
       ('নিকটায়নের হার যোগফল হয় কেন?','একই সময়ে উভয়ের চলা পথ তাদের মধ্যের বিচ্ছেদ কমায়। তাই প্রতি সেকেন্ডে বিচ্ছেদ দুই দ্রুতির যোগফল পরিমাণ কমে।'),
       'কত সময় পরে দেখা হবে?',f't = {gap}/({v}+{w}) = {T} s।',
       'দেখা হওয়ার অবস্থান A-এর শুরু থেকে নির্ণয় করে দুই পথের যোগফল যাচাই করো।',f'A যায় {v}×{T} = {v*T} m। B যায় {w}×{T} = {w*T} m। যোগ = {gap} m, প্রাথমিক বিচ্ছেদের সমান। অবস্থান A-এর শুরু থেকে B-এর দিকে {v*T} m।',dict(v=v,w=w,gap=gap))
    # 16: overtaking with head start.
    fast=12+n*2;slow=8+n;T=10+n*3;gap=(fast-slow)*T
    cq('cq-overtake',n,f'A গাড়ি B-এর {gap} m পেছনে। একই দিকে A ও B যথাক্রমে {fast} m/s এবং {slow} m/s ধ্রুব বেগে চলে। গাড়িগুলোকে বিন্দু ধরা হয়েছে।',DEF_V,
       ('ধরার সময় পেতে শুধু A-এর দ্রুতি দিয়ে দূরত্ব ভাগ করা যায় না কেন?','A এগোতে থাকলেও B-ও এগোয়। বিচ্ছেদ কমার হার A ও B-এর বেগের পার্থক্য।'),
       'A কত সময় পরে B-কে ধরবে?',f't = {gap}/({fast}−{slow}) = {T} s।',
       'ধরার মুহূর্তে A-এর শুরু থেকে দুই গাড়ির অবস্থান সমান দেখাও।',f'A-এর অবস্থান = {fast}×{T} = {fast*T} m। B-এর অবস্থান = {gap}+{slow}×{T} = {fast*T} m। শুরুতে এগিয়ে থাকা অবস্থানটি B-এর হিসাবে যোগ করায় উভয়ের অবস্থান মিলে।',dict(fast=fast,slow=slow,gap=gap))
    # 17: accelerating catches constant speed from same start.
    a=2+n;v=6+n*2;T=F(2*v,a);x=v*T
    cq('cq-catch-accelerating',n,f'A ও B একই স্থান থেকে একই সময়ে একই সরলদিকে শুরু করে। A স্থির থেকে {a} m/s² ধ্রুব ত্বরণে চলে, B চলে {v} m/s ধ্রুব বেগে। এই গতি বজায় থাকে।',DEF_A,
       ('শুরুর অবস্থান সমান হলেই শুরুতে বেগ সমান নয় কেন?','অবস্থান ও তার পরিবর্তনের হার আলাদা বিষয়। এখানে A-এর আদিবেগ শূন্য, কিন্তু B-এর আদিবেগ অশূন্য।'),
       'শুরু বাদে কখন আবার একই অবস্থানে হবে?',f'½at² = vt; t ≠ 0 হলে t = 2v/a = 2×{v}/{a} ≈ {fmt(T)} s।',
       'সেই অবস্থান ও ঐ মুহূর্তে দুই বেগ তুলনা করো।',f'x = vt ≈ {fmt(x)} m। A-এর v_A = at = 2v = {2*v} m/s; B-এর {v} m/s। একই অবস্থানে এসেও A-এর বেগ B-এর দ্বিগুণ; অবস্থান-সমতা বেগ-সমতা নয়।',dict(a=a,v=v))
    # 18: delayed uniform start.
    slow=4+n;fast=slow+4;delay=6+n;T=F(slow*delay,fast-slow);x=fast*T
    cq('cq-delayed-start',n,f'এক দৌড়বিদ একই সরলপথে {slow} m/s ধ্রুব বেগে শুরু করে। {delay} s পরে একই স্থান থেকে দ্বিতীয়জন {fast} m/s ধ্রুব বেগে তার পেছনে চলতে শুরু করে।',DEF_S,
       ('দুইজনের সময় আলাদা করে নেওয়া দরকার কেন?','প্রথমজন আগে শুরু করেছে। দ্বিতীয়জনের চলার সময় t হলে প্রথমজনের সময় t এবং বিলম্বের যোগফল।'),
       'দ্বিতীয়জন শুরু করার কত সময় পরে প্রথমজনকে ধরবে?',f'{fast}t = {slow}(t+{delay}); t = {slow}×{delay}/({fast}−{slow}) = {fmt(T)} s।',
       'ধরার অবস্থান ও প্রথমজনের মোট সময় নির্ণয় করে যাচাই করো।',f'x = {fast}×{fmt(T)} = {fmt(x)} m। প্রথমজনের মোট সময় = {fmt(T+delay)} s; তার পথ = {slow}×{fmt(T+delay)} = {fmt(x)} m। সময়ের মূলবিন্দু ঠিক রাখলে ফল মিলে।',dict(slow=slow,fast=fast,delay=delay))
    # 19: free fall known time.
    g=10;t=3+n;h=F(g*t*t,2);v=g*t
    cq('cq-drop-time',n,f'একটি পাথর স্থির অবস্থা থেকে ছাড়া হলো। {t} s পরে মাটিতে লাগে। g = {g} m/s², বায়ুর বাধা নেই; নিচের দিক ধনাত্মক ধরো।',('মুক্তপতন কী?','শুধু মহাকর্ষের প্রভাবে চলা, যেখানে বায়ুর বাধাসহ অন্য প্রভাব উপেক্ষা করা হয়।'),WHY_G,
       'যে উচ্চতা থেকে ছাড়া হয়েছিল তা নির্ণয় করো।',f'h = ½gt² = ½×{g}×{t}² = {fmt(h)} m।',
       'মাটিতে লাগার ঠিক আগের বেগ নির্ণয় করে অন্য সূত্রে যাচাই করো।',f'v = gt = {v} m/s, নিচে। আবার v² = 2gh = {v*v}, তাই v = +{v} m/s। আঘাতের পরের গতি সম্পর্কে এই সূত্র কিছু বলে না।',dict(g=g,t=t))
    # 20: free fall known height.
    g=10;t=2+n;h=F(g*t*t,2);v=g*t
    cq('cq-drop-height',n,f'একটি বল {fmt(h)} m উচ্চতা থেকে স্থির অবস্থা হতে ছাড়া হয়। g = {g} m/s² ও বায়ুর বাধা নেই। মাটি পর্যন্ত পতন বিবেচনা করো।',DEF_A,WHY_G,
       'পতনকাল নির্ণয় করো।',f'h = ½gt² থেকে t² = 2×{fmt(h)}/{g} = {t*t}; t = {t} s। সময়ের ধনাত্মক মূল নেওয়া হয়েছে।',
       'একই উচ্চতা থেকে দ্বিগুণ ভরের বল ছাড়লে পতনকাল ও আঘাত-পূর্ব দ্রুতি কী হবে?',f'মূল বলের v = gt = {v} m/s। আদর্শ সমীকরণে ভর নেই; দ্বিতীয় বলের সময়ও {t} s ও আঘাত-পূর্ব দ্রুতিও {v} m/s। ভর বাড়া মানেই এই আদর্শ অবস্থায় আগে পড়া নয়।',dict(g=g,h=h))
    # 21: thrown downward.
    u=5+n;g=10;t=2+n;h=u*t+F(g*t*t,2);v=u+g*t
    cq('cq-downward-throw',n,f'এক বলকে উঁচু স্থান থেকে সোজা নিচে {u} m/s আদিবেগে ছোড়া হলো। {t} s পরে মাটিতে লাগে। g = {g} m/s² ও বায়ুর বাধা নেই।',DEF_A,WHY_G,
       'নিক্ষেপস্থানের উচ্চতা নির্ণয় করো।',f'নিচে ধনাত্মক; h = ut+½gt² = {u}×{t}+½×{g}×{t}² = {fmt(h)} m।',
       'শেষবেগ নির্ণয় করে u = 0 ধরে হিসাব করলে উচ্চতায় কত ভুল হতো দেখাও।',f'v = u+gt = {v} m/s নিচে। u বাদ দিলে উচ্চতা {fmt(F(g*t*t,2))} m হতো; কম আসত ut = {u*t} m। ছাড়া ও ছোড়ার পার্থক্য উপেক্ষা করা যাবে না।',dict(u=u,g=g,t=t))
    # 22: vertical throw round trip.
    u=20+n*10;g=10;top=F(u,g);height=F(u*u,2*g);totalT=2*top
    cq('cq-upward-roundtrip',n,f'ভূমি থেকে একটি বল সোজা ওপরে {u} m/s বেগে ছোড়া হয় এবং একই উচ্চতায় ফিরে আসে। g = {g} m/s² ও বায়ুর বাধা নেই; ওপরে ধনাত্মক।',DEF_V,
       ('সর্বোচ্চ বিন্দুতে ত্বরণ শূন্য নয় কেন?','সেখানে মুহূর্তে বেগ শূন্য, কিন্তু মহাকর্ষের দিক ও প্রভাব অক্ষুণ্ণ। ত্বরণ সবসময় −g।'),
       'সর্বোচ্চ উচ্চতা ও সেখানে পৌঁছানোর সময় নির্ণয় করো।',f'tউপর = u/g = {fmt(top)} s। h = u²/(2g) = {fmt(height)} m।',
       'পূর্ণ যাত্রার সময়, মোট দূরত্ব ও সরণ নির্ণয় করো।',f'সময় = 2u/g = {fmt(totalT)} s। মোট পথ = 2h = {fmt(2*height)} m; সরণ = 0 m। তাই গড় বেগ শূন্য, কিন্তু গড় দ্রুতি = 2h/(2u/g) = {fmt(F(u,2))} m/s।',dict(u=u,g=g))
    # 23: upward instant while descending.
    u=20+n*10;g=10;t=F(3*u,2*g);v=u-g*t;s=u*t-F(g*t*t,2)
    cq('cq-upward-instant',n,f'ভূমি থেকে বল সোজা ওপরে {u} m/s বেগে ছোড়া হলো। g = {g} m/s², বায়ুর বাধা নেই। নিক্ষেপের {fmt(t)} s পরের অবস্থা বিচার করো; ওপরে ধনাত্মক।',DEF_A,WHY_SIGN,
       'প্রদত্ত মুহূর্তে বেগ ও উচ্চতা নির্ণয় করো।',f'v = u−gt = {fmt(v)} m/s। y = ut−½gt² = {fmt(s)} m।',
       'বলটি তখন উঠছে না নামছে এবং মাটিতে পড়েছে কি না—সময় ও চিহ্ন দিয়ে বিচার করো।',f'চূড়ায় সময় u/g = {fmt(F(u,g))} s; ফেরার সময় 2u/g = {fmt(F(2*u,g))} s। প্রদত্ত {fmt(t)} s মাঝখানে, বেগ {fmt(v)} m/s ঋণাত্মক ও উচ্চতা {fmt(s)} m ধনাত্মক; তাই মাটির ওপরে থেকে নামছে।',dict(u=u,g=g,t=t))
    # 24: nth second.
    u=2+n;a=2+n;k=3+n;sN=u*k+F(a*k*k,2);prev=u*(k-1)+F(a*(k-1)**2,2);part=sN-prev
    cq('cq-nth-second',n,f'একটি বস্তু একই সরলদিকে +{u} m/s আদিবেগে +{a} m/s² ধ্রুব ত্বরণে চলে। যাত্রার প্রথম {k} s এবং শুধু {k}-তম সেকেন্ড আলাদা করে বিবেচনা করো।',DEF_S,
       ('প্রথম n সেকেন্ড ও n-তম সেকেন্ড এক নয় কেন?','প্রথমটি শুরু থেকে n সেকেন্ড পর্যন্ত পুরো ব্যবধান। দ্বিতীয়টি (n−1) থেকে n সেকেন্ডের মাত্র এক সেকেন্ড।'),
       'প্রথম প্রদত্ত সময়ের মোট পথ নির্ণয় করো।',f's({k}) = {u}×{k}+½×{a}×{k}² = {fmt(sN)} m।',
       'শুধু শেষ এক সেকেন্ডের পথ নির্ণয় করে গড় দিয়ে যাচাই করো।',f's({k-1}) = {fmt(prev)} m; পার্থক্য = {fmt(part)} m। ঐ সেকেন্ডের প্রান্তবেগ {u+a*(k-1)} ও {u+a*k} m/s; গড় × 1 = {fmt(part)} m। পুরো {k} s-এর পথের সঙ্গে এটি গুলানো যাবে না।',dict(u=u,a=a,k=k))
    # 25: last second of free fall.
    t=3+n;g=10;h=F(g*t*t,2);last=F(g,2)*(2*t-1)
    cq('cq-last-second-fall',n,f'একটি বল স্থির অবস্থা থেকে মোট {t} s মুক্তভাবে পড়ে মাটিতে লাগে। g = {g} m/s², বায়ুর বাধা নেই। পতনের শেষ এক সেকেন্ডও মাটিতে লাগার আগের অংশ।',('মুক্তপতনে স্থির থেকে ছাড়ার আদিবেগ কত?','শূন্য।'),WHY_G,
       'মোট পতনের উচ্চতা নির্ণয় করো।',f'h = ½gt² = ½×{g}×{t}² = {fmt(h)} m।',
       'শেষ এক সেকেন্ডে অতিক্রান্ত পথ ও মোট পথের ভগ্নাংশ নির্ণয় করো।',f'শেষ পথ = ½g[{t}²−{t-1}²] = {fmt(last)} m। ভগ্নাংশ = {fmt(last)}/{fmt(h)} ≈ {fmt(last/h)}। দ্রুতির মান বাড়ে বলে সমান সময়েও শেষের পথ বেশি।',dict(t=t,g=g))
    # 26: comparing stopping distances.
    u=10+n*2;b=2+n;d1=F(u*u,2*b);d2=4*d1
    cq('cq-double-speed-brake',n,f'একই রাস্তার দুই গাড়ির আদিদ্রুতি যথাক্রমে {u} m/s ও {2*u} m/s। ব্রেক চাপা শুরু থেকে উভয়ের মন্দনের মান ধ্রুব {b} m/s²। প্রতিক্রিয়াকাল নেই।',DEF_A,
       ('ব্রেকিং দূরত্বে আদিবেগের বর্গ আসে কেন?','v² = u²−2bs-এ থামার সময় v = 0। তাই s = u²/(2b)।'),
       'প্রথম গাড়ির থামার দূরত্ব ও সময় নির্ণয় করো।',f's₁ = {u}²/(2×{b}) = {fmt(d1)} m। t₁ = {u}/{b} ≈ {fmt(F(u,b))} s।',
       'দ্বিতীয় গাড়ির ফল বের করে দ্রুতির দ্বিগুণ হওয়া নিরাপত্তায় কী বোঝায় বিচার করো।',f's₂ = {2*u}²/(2×{b}) = {fmt(d2)} m = 4s₁। t₂ = {fmt(F(2*u,b))} s = 2t₁। একই মন্দনে দ্বিগুণ দ্রুতি চারগুণ ব্রেকিং পথ চায়; দূরত্বের প্রভাব সরল দ্বিগুণ নয়।',dict(u=u,b=b))
    # 27: reaction + brake.
    u=15+n*3;reaction=F(4+n,10);b=3;dr=u*reaction;db=F(u*u,2*b);total=dr+db
    cq('cq-reaction-braking',n,f'এক গাড়ি {u} m/s দ্রুতিতে চলছে। চালকের প্রতিক্রিয়াকাল {fmt(reaction)} s; এ সময় দ্রুতি অপরিবর্তিত। এরপর {b} m/s² ধ্রুব মন্দনে গাড়ি থামে। বিপদ দেখে গণনা শুরু করো।',DEF_S,
       ('মোট থামার দূরত্বে প্রতিক্রিয়া-দূরত্ব যোগ করা দরকার কেন?','ব্রেক কার্যকর হওয়ার আগেও গাড়ি চলছে। শুধু ব্রেকিং পথ নিলে সেই অতিরিক্ত চলা বাদ পড়ে।'),
       'প্রতিক্রিয়া-দূরত্ব ও ব্রেকিং-দূরত্ব নির্ণয় করো।',f'dᵣ = {u}×{fmt(reaction)} = {fmt(dr)} m। dᵦ = u²/(2b) = {fmt(db)} m।',
       'বাধা মোট প্রয়োজনীয় পথের 1 m কম দূরে থাকলে গাড়ি বাধার আগে থামবে কি? হিসাব দাও।',f'মোট প্রয়োজন = {fmt(dr)}+{fmt(db)} = {fmt(total)} m। বাধার দূরত্ব = {fmt(total-1)} m। গাড়ির প্রয়োজন এর চেয়ে 1 m বেশি; তাই প্রদত্ত আদর্শ গতিতে বাধার আগে থামতে পারবে না। বাস্তবের অতিরিক্ত নিরাপত্তা-দূরত্ব এখানে ধরা হয়নি।',dict(u=u,reaction=reaction,b=b))
    # 28: train over bridge at constant speed.
    L=100+n*20;bridge=150+n*30;v=10+n*2;time=F(L+bridge,v)
    cq('cq-train-bridge',n,f'একটি {L} m দীর্ঘ ট্রেন {v} m/s ধ্রুব দ্রুতিতে {bridge} m দীর্ঘ সেতু পার হয়। ইঞ্জিন সেতুর প্রথম প্রান্তে পৌঁছানো থেকে শেষ বগি অপর প্রান্ত ছাড়ার সময় বিবেচনা করো।',DEF_S,
       ('ট্রেনের দৈর্ঘ্যও চলার পথে যোগ করতে হয় কেন?','ইঞ্জিন শেষ প্রান্তে পৌঁছালেও শেষ বগি সেতুর ওপর থাকে। পুরো ট্রেন ছাড়াতে ইঞ্জিনকে আরও ট্রেনের দৈর্ঘ্য অগ্রসর হতে হয়।'),
       'পুরো ট্রেন সেতু পার হতে সময় নির্ণয় করো।',f'ইঞ্জিনের চলা পথ = {L}+{bridge} = {L+bridge} m। t = {L+bridge}/{v} = {fmt(time)} s।',
       'একটি খুঁটি পার হওয়ার সময়ের সঙ্গে তুলনা করে অতিরিক্ত সময়ের কারণ দেখাও।',f'খুঁটি পার হতে সময় = {L}/{v} = {fmt(F(L,v))} s। পার্থক্য = {bridge}/{v} = {fmt(F(bridge,v))} s। সেতুর বিস্তৃতি শূন্য নয় বলেই এই অতিরিক্ত সময় লাগে।',dict(L=L,bridge=bridge,v=v))
    # 29: equal distances unequal speeds.
    d=120+n*60;v=6+n;w=10+n;t1=F(d,v);t2=F(d,w);avg=F(2*d)/(t1+t2)
    cq('cq-equal-distance-average',n,f'এক গাড়ি প্রথম {d} m পথ {v} m/s ধ্রুব দ্রুতিতে এবং পরের {d} m পথ {w} m/s ধ্রুব দ্রুতিতে চলে। পর্ববদলের সময় ও কোনো বিরতি উপেক্ষা করো।',DEF_S,
       ('এখানে দুই দ্রুতির গাণিতিক গড় সরাসরি নেওয়া যায় না কেন?','দূরত্ব সমান কিন্তু ভিন্ন দ্রুতিতে সময় সমান নয়। গড় দ্রুতিতে সময়ের সঠিক ওজন দরকার।'),
       'দুই পর্বের সময় ও পুরো যাত্রার গড় দ্রুতি নির্ণয় করো।',f't₁ = {d}/{v} ≈ {fmt(t1)} s; t₂ = {d}/{w} ≈ {fmt(t2)} s। গড় = {2*d}/(t₁+t₂) ≈ {fmt(avg)} m/s।',
       'গাণিতিক গড়ের সঙ্গে সঠিক গড় তুলনা করে ধীর পর্বের প্রভাব বোঝাও।',f'গাণিতিক গড় = ({v}+{w})/2 = {fmt(F(v+w,2))} m/s; সঠিক গড় ≈ {fmt(avg)} m/s, যা কম। ধীর পর্বে বেশি সময় কাটে; তাই সেটির প্রভাব বেশি। সঠিক সূত্র 2v₁v₂/(v₁+v₂)।',dict(d=d,v=v,w=w))
    # 30: signed piecewise constant velocities.
    v=5+n;t1=6+n;w=3+n;t2=4+n;east=v*t1;west=w*t2;net=east-west;dist=east+west;tt=t1+t2
    cq('cq-signed-velocity-intervals',n,f'এক বস্তু প্রথম {t1} s পূর্বদিকে {v} m/s ধ্রুব বেগে, পরের {t2} s পশ্চিমদিকে {w} m/s ধ্রুব বেগে চলে। পর্ববদলের সময় উপেক্ষা করো; পূর্ব ধনাত্মক।',DEF_V,WHY_AREA,
       'মোট সরণ ও মোট দূরত্ব নির্ণয় করো।',f'পূর্বের পথ = {east} m, পশ্চিমের = {west} m। সরণ = {east}−{west} = +{net} m। দূরত্ব = {east}+{west} = {dist} m।',
       'গড় বেগ ও গড় দ্রুতি নির্ণয় করে v-t ক্ষেত্রফলের চিহ্নের ভূমিকা ব্যাখ্যা করো।',f'মোট সময় = {tt} s। গড় বেগ = {net}/{tt} ≈ {fmt(F(net,tt))} m/s পূর্বে; গড় দ্রুতি = {dist}/{tt} ≈ {fmt(F(dist,tt))} m/s। পশ্চিমের ক্ষেত্রফল সরণে ঋণাত্মক কিন্তু দূরত্বে তার পরমমান যোগ হয়।',dict(v=v,t1=t1,w=w,t2=t2))

assert Counter(q['type'] for q in items)=={'MCQ':300,'CQ':150,'SQ':100}
assert len(set(q['text'] for q in items))==550

def encode(x):return json.dumps(x,ensure_ascii=False,indent=2)+'\n'
def artifact(p,s):
    if '--check' in sys.argv:assert p.exists() and p.read_text()==s,f'Stale: {p}'
    else:p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s)

mcqs=[q for q in items if q['type']=='MCQ']
slices={'mcq-1':mcqs[:150],'mcq-2':mcqs[150:],'cq':[q for q in items if q['type']=='CQ'],'sq':[q for q in items if q['type']=='SQ']}
for name,rows in slices.items():
    b=dict(category='Class 9',subject='পদার্থবিজ্ঞান',topic=TOPIC,book='নিজস্ব অনুশীলনী; উৎস পৃষ্ঠা/বোর্ড আরোপ নয়',edition='নবম–দশম গতি অনুশীলনী খসড়া v1; শিক্ষক যাচাই বাকি',sourceUrl='https://github.com/saifulsirictdev/Proshnobook_com',lang='Bangla',items=rows)
    s=encode(b);assert len(s.encode())<750000 and len(rows)<=200
    artifact(OUT/f'{name}.json',s)
