    for i,q in enumerate([x for x in items if x['type']==kind],1):
        b=f'<h3>{i}. {html.escape(q["text"])}</h3>'
        if kind=='MCQ':
            b+='<div class="options">'+''.join(f'<p>{k}. {html.escape(v)}</p>' for k,v in q['options'].items())+'</div>'
            b+=f'<p class="answer">উত্তর: {q["correct"]} — {html.escape(q["explanation"])}</p>'
        elif kind=='CQ':
            b+=''.join(f'<p><b>{p["label"]}) ({p["marks"]}) {html.escape(p["question"])}</b></p><p class="answer">{html.escape(p["solution"])}</p>' for p in q['parts'])
        else:b+=f'<p class="answer">{html.escape(q["explanation"])}</p>'
        blocks.append('<article>'+b+'</article>')
